    $ids = $options['ids'] ?? [];
    $searchId   = $ids['search'] ?? ($prefix . 'SearchInput');
    $sortId     = $ids['sort']   ?? ($prefix . 'SortSelect');
    $filterWrap = $ids['wrap']   ?? ($prefix . 'FilterWrap');
    $filterBtn  = $ids['btn']    ?? ($prefix . 'FilterBtn');
